-- TEST FIXTURE ONLY: subset of the upstream FreeRADIUS 3.x MySQL schema (raddb/mods-config/sql/main/mysql/schema.sql)
-- plus the nas table. Used only by the local throwaway MariaDB integration test.
CREATE DATABASE IF NOT EXISTS radius;
CREATE TABLE radius.radcheck (id int unsigned NOT NULL auto_increment, username varchar(64) NOT NULL default '', attribute varchar(64) NOT NULL default '', op char(2) NOT NULL DEFAULT '==', value varchar(253) NOT NULL default '', PRIMARY KEY (id), KEY username (username(32))) ENGINE=InnoDB;
CREATE TABLE radius.radgroupcheck (id int unsigned NOT NULL auto_increment, groupname varchar(64) NOT NULL default '', attribute varchar(64) NOT NULL default '', op char(2) NOT NULL DEFAULT '==', value varchar(253) NOT NULL default '', PRIMARY KEY (id), KEY groupname (groupname(32))) ENGINE=InnoDB;
CREATE TABLE radius.radgroupreply (id int unsigned NOT NULL auto_increment, groupname varchar(64) NOT NULL default '', attribute varchar(64) NOT NULL default '', op char(2) NOT NULL DEFAULT '=', value varchar(253) NOT NULL default '', PRIMARY KEY (id), KEY groupname (groupname(32))) ENGINE=InnoDB;
CREATE TABLE radius.radusergroup (id int unsigned NOT NULL auto_increment, username varchar(64) NOT NULL default '', groupname varchar(64) NOT NULL default '', priority int(11) NOT NULL default '1', PRIMARY KEY (id), KEY username (username(32))) ENGINE=InnoDB;
CREATE TABLE radius.radacct (radacctid bigint(21) NOT NULL auto_increment, acctsessionid varchar(64) NOT NULL default '', acctuniqueid varchar(32) NOT NULL default '', username varchar(64) NOT NULL default '', nasipaddress varchar(15) NOT NULL default '', acctstarttime datetime NULL default NULL, acctupdatetime datetime NULL default NULL, acctstoptime datetime NULL default NULL, acctsessiontime int(12) unsigned default NULL, acctinputoctets bigint(20) default NULL, acctoutputoctets bigint(20) default NULL, acctterminatecause varchar(32) NOT NULL default '', framedipaddress varchar(15) NOT NULL default '', PRIMARY KEY (radacctid), UNIQUE KEY acctuniqueid (acctuniqueid)) ENGINE=InnoDB;
CREATE TABLE radius.nas (id int(10) NOT NULL auto_increment, nasname varchar(128) NOT NULL, shortname varchar(32), type varchar(30) DEFAULT 'other', ports int(5), secret varchar(60) DEFAULT 'secret' NOT NULL, server varchar(64), community varchar(50), description varchar(200) DEFAULT 'RADIUS Client', PRIMARY KEY (id)) ENGINE=InnoDB;
CREATE TABLE radius.userbillinfo (id int unsigned NOT NULL auto_increment, username varchar(128), creditcardnumber varchar(200), PRIMARY KEY (id)) ENGINE=InnoDB;
